using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 changed the default discriminator property from
            // "Discriminator" to "$type". Preserve the old property name so
            // existing 500K documents (and direct SQL queries that reference
            // c.Discriminator) keep working without a data migration.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 changed the default id format from "EntityName|Key"
            // to just "Key". Preserve the old format so existing documents
            // (with ids like "Product|123") remain readable.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id).ToJsonProperty("id");
            entity.UseETagConcurrency();
        });

        // EF Core 9 requires the id property mapping to be set explicitly
        // when preserving the legacy "EntityName|Key" id format.
        modelBuilder.Entity<Product>()
            .Property(p => p.Id)
            .HasConversion(
                id => $"Product|{id}",
                cosmosId => int.Parse(cosmosId.Replace("Product|", "")));

        // HasIndex() is no longer supported by the Cosmos provider in EF 9.
        // Cosmos DB manages indexing automatically via its indexing policy;
        // configure custom indexes through the Azure portal or ARM templates.
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

